{
  "apiVersion": 1,
  "type": "component.detail.props",
  "package": "@astryxdesign/core",
  "data": [
    {
      "name": "src",
      "type": "string",
      "description": "Primary image source URL."
    },
    {
      "name": "fallbackSrc",
      "type": "string",
      "description": "Fallback image when primary fails."
    },
    {
      "name": "name",
      "type": "string",
      "description": "User name for initials and alt text."
    },
    {
      "name": "alt",
      "type": "string",
      "description": "Alt text (falls back to name)."
    },
    {
      "name": "size",
      "type": "'xsm' | 'sm' | 'md' | 'lg' | 'xl' | 16 | 20 | 24 | 32 | 36 | 40 | 48 | 60 | 64 | 72 | 96 | 128 | 144 | 180",
      "description": "Avatar size: named sizes are 'xsm' (20px), 'sm' (24px), 'md' (36px), 'lg' (48px), and 'xl' (128px); numeric sizes must be one of the pixel values listed in the type. Inside an AvatarGroup, the group's size always overrides this prop, including when the group uses its default size.",
      "default": "'md'"
    },
    {
      "name": "shape",
      "type": "'circle' | 'rounded' | 'square'",
      "description": "Shape variant of the avatar. 'circle' (default) stays fully round. 'rounded' uses the element radius token so it matches UI corner rounding and can be set globally via theme. 'square' has no radius. Status dot positioning adapts automatically: 4-o'clock on circle, bottom-right corner on rounded/square.",
      "default": "'circle'"
    },
    {
      "name": "status",
      "type": "ReactNode",
      "description": "Corner content for status indicators. AvatarStatusDot reports its `label` to the avatar, which composes it into the accessible name (e.g. \"Jane Doe, Online\") so screen readers announce the status. Reporting goes through context, so it still works when the dot sits inside a wrapper component of your own.",
      "slotElements": [
        {
          "__element": "AvatarStatusDot",
          "props": {
            "variant": "success",
            "label": "Online"
          }
        }
      ]
    },
    {
      "name": "tooltip",
      "type": "string | boolean",
      "description": "Tooltip shown on hover and keyboard focus. Omitted or true shows the avatar's name; a string shows that text instead; false shows no tooltip. Not auto-disabled when wrapped in your own Tooltip/HoverCard. Set tooltip={false} if you supply your own overlay. No tooltip is shown when tooltip is true/omitted and there is no name.",
      "default": "true"
    },
    {
      "name": "href",
      "type": "string",
      "description": "When set, the avatar renders as an interactive link (`<a>` or a custom link component) pointing here. This follows the same element-swap rule as Button. Requires a meaningful accessible name via `alt` or `name`: an interactive avatar without one warns in development. Inside an AvatarGroup, interactive avatars share a single Tab stop and are reached with arrow keys."
    },
    {
      "name": "as",
      "type": "ElementType",
      "description": "Custom link component used when `href` is set (e.g. `next/link`). Overrides the provider-level LinkProvider default. Only applies with `href`."
    },
    {
      "name": "target",
      "type": "string",
      "description": "Link target attribute. Only applies with `href`."
    },
    {
      "name": "rel",
      "type": "string",
      "description": "Link rel attribute. Only applies with `href`."
    },
    {
      "name": "onClick",
      "type": "(e: MouseEvent) => void",
      "description": "Click handler. When set without `href`, the avatar renders as a focusable `<button type=\"button\">`. Requires a meaningful accessible name via `alt` or `name`: an interactive avatar without one warns in development."
    }
  ],
  "meta": {
    "answeredBy": {
      "cli": "0.7.12",
      "core": "0.7.12",
      "copy": "starting"
    }
  }
}
